INSERT INTO fee_schedule_tb (
    gateway_id,
    version_code,
    txn_type,
    effective_from,
    effective_to,
    settlement_currency,
    percent_rate,
    fixed_fee,
    min_fee,
    fx_markup_bps,
    failed_attempt_fee,
    refund_returns_percent_fee
)
SELECT
    g.id,
    v.version_code,
    v.txn_type,
    v.effective_from,
    v.effective_to,
    g.settlement_currency,
    v.percent_rate,
    v.fixed_fee,
    v.min_fee,
    v.fx_markup_bps,
    v.failed_attempt_fee,
    FALSE
FROM payment_gateway_tb AS g
JOIN (
    VALUES
        ('NSP', '2025-01', 'payment', DATE '2025-01-01', DATE '2026-03-31', 0.029000, 0.3000, 0.5000, 150, 0.0000),
        ('NSP', '2025-01', 'refund',  DATE '2025-01-01', DATE '2026-03-31', 0.000000, 0.3000, 0.0000, 150, 0.0000),
        ('NSP', '2026-04', 'payment', DATE '2026-04-01', NULL::date,       0.026000, 0.3000, 0.5000, 200, 0.0000),
        ('NSP', '2026-04', 'refund',  DATE '2026-04-01', NULL::date,       0.000000, 0.3000, 0.0000, 200, 0.0000),
        ('HFL', '2025-01', 'payment', DATE '2025-01-01', NULL::date,       0.018000, 0.0000, 0.0000,  80, 0.0000),
        ('HFL', '2025-01', 'refund',  DATE '2025-01-01', NULL::date,       0.000000, 1.0000, 0.0000,  80, 0.0000),
        ('CDG', '2025-01', 'payout',  DATE '2025-01-01', DATE '2026-05-31', 0.005000, 2.0000, 2.0000, 100, 0.2500),
        ('CDG', '2025-01', 'refund',  DATE '2025-01-01', DATE '2026-05-31', 0.000000, 2.0000, 0.0000, 100, 0.0000),
        ('CDG', '2026-06', 'payout',  DATE '2026-06-01', NULL::date,       0.005000, 3.5000, 3.5000, 100, 0.2500),
        ('CDG', '2026-06', 'refund',  DATE '2026-06-01', NULL::date,       0.000000, 3.5000, 0.0000, 100, 0.0000)
) AS v (
    gateway_code,
    version_code,
    txn_type,
    effective_from,
    effective_to,
    percent_rate,
    fixed_fee,
    min_fee,
    fx_markup_bps,
    failed_attempt_fee
) ON v.gateway_code = g.code
ON CONFLICT (gateway_id, version_code, txn_type) DO NOTHING;

