INSERT INTO document_tb (
    doc_code,
    gateway_id,
    doc_type,
    version_code,
    title,
    effective_from,
    effective_to,
    source_path
)
SELECT
    d.doc_code,
    g.id,
    d.doc_type,
    d.version_code,
    d.title,
    d.effective_from,
    d.effective_to,
    d.source_path
FROM (
    VALUES
        ('NSP-FEE-2025-01', 'NSP', 'fee_schedule', '2025-01', 'NorthstarPay fee schedule 2025-01', DATE '2025-01-01', DATE '2026-03-31', 'docs/source/northstar/fee-schedule-2025-01.md'),
        ('NSP-FEE-2026-04', 'NSP', 'fee_schedule', '2026-04', 'NorthstarPay fee schedule 2026-04', DATE '2026-04-01', NULL::date, 'docs/source/northstar/fee-schedule-2026-04.md'),
        ('NSP-FX-2025-01', 'NSP', 'fx_rules', '2025-01', 'NorthstarPay FX rules 2025-01', DATE '2025-01-01', DATE '2026-03-31', 'docs/source/northstar/fx-rules-2025-01.md'),
        ('NSP-FX-2026-04', 'NSP', 'fx_rules', '2026-04', 'NorthstarPay FX rules 2026-04', DATE '2026-04-01', NULL::date, 'docs/source/northstar/fx-rules-2026-04.md'),
        ('HFL-FEE-2025-01', 'HFL', 'fee_schedule', '2025-01', 'HarborFlow fee schedule 2025-01', DATE '2025-01-01', NULL::date, 'docs/source/harborflow/fee-schedule-2025-01.md'),
        ('HFL-FX-2025-01', 'HFL', 'fx_rules', '2025-01', 'HarborFlow FX rules 2025-01', DATE '2025-01-01', NULL::date, 'docs/source/harborflow/fx-rules-2025-01.md'),
        ('CDG-FEE-2025-01', 'CDG', 'fee_schedule', '2025-01', 'CedarGate fee schedule 2025-01', DATE '2025-01-01', DATE '2026-05-31', 'docs/source/cedargate/fee-schedule-2025-01.md'),
        ('CDG-FEE-2026-06', 'CDG', 'fee_schedule', '2026-06', 'CedarGate fee schedule 2026-06', DATE '2026-06-01', NULL::date, 'docs/source/cedargate/fee-schedule-2026-06.md'),
        ('CDG-FX-2025-01', 'CDG', 'fx_rules', '2025-01', 'CedarGate FX rules 2025-01', DATE '2025-01-01', NULL::date, 'docs/source/cedargate/fx-rules-2025-01.md')
) AS d (
    doc_code,
    gateway_code,
    doc_type,
    version_code,
    title,
    effective_from,
    effective_to,
    source_path
)
JOIN payment_gateway_tb AS g ON g.code = d.gateway_code
ON CONFLICT (doc_code) DO NOTHING;

